class FileHandle {
    FILE* fp;
public:
    explicit FileHandle(const char* path) {
        fp = fopen(path, "r");
    }
    // The RAII Guarantee: Destructor releases resource
    ~FileHandle() { 
        if (fp) fclose(fp);
    }

    // Prevent accidental copying of the resource handle
    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;
};

// --- Standard Library: Memory RAII (std::unique_ptr) ---

struct Config {};

void process_config() {
    // Resource acquired upon creation (heap allocation)
    std::unique_ptr<Config> ptr = std::make_unique<Config>();

    // Ownership is unique and guaranteed

    if (rand() % 2) {
        return; // Config deleted here automatically
    }

    // ptr leaves scope, Config destructor called.
}

// --- Standard Library: Concurrency RAII (std::lock_guard) ---

std::mutex shared_mtx;
int counter = 0;

void increment() {
    // Resource (lock) acquired upon object creation
    std::lock_guard<std::mutex> lock(shared_mtx);

    // Critical section
    counter++; 

    // Lock automatically released when 'lock' leaves scope (via destructor)
    // even if an exception occurs.
}
